import logging
import traceback

from ute_common_abstract_core import instance_loader
from ute_common_abstract_core.exceptions import InvalidConfigurationContent
from ute_ue.config import loggers as ta_ue_logging
from ute_ue.utils.proxy_mngr import ProxiedCfgFileBasedUePool

# TODO: What about moving it to versioning.py
# variables used to deploy proxy service via proxy mngr
MIN_REQUIRED_UEPROXY_VER = '1.11.0'
MIN_REQUIRED_ACCESS_VER = '1.10.2'


class TafUeIphonePool(ProxiedCfgFileBasedUePool):
    """
    Pool of iPhone UEs available to use by tests.

    It manages UEs used by tests: reserves given UE for test exclusive use and later releases UE back to pool.

    get_ue() searches for UE having ue_characteristics specified by test - either finds such UE
    or raises informative exception.

    Pool should track issued UEs to not issue UE-in-use.
    UE must come back to pool via release_ue() before it can be issued once more via get_ue().
    """

    def __init__(self, config_file_path=None, inline_config=None):
        """

        :param config_file_path:
        :param inline_config:
        """
        self.inline_config = inline_config
        super().__init__(config_file_path, inline_config)

        raw_logger = logging.getLogger("ute_ue")
        self.rpc_clients = set()
        self.logger = ta_ue_logging.LoggerAdapter4EmptyExtra(raw_logger, {'area': 'UEPOOL'})

    def create_device(self, device_name, device_config):
        """
        Create instance of device

        :param device_name: name of UE
        :param device_config: configuration of UE
        :return: device instance
        """
        try:
            self.logger.debug(f"Executing create_device with name {device_name} and configuration {device_config}")
            config = device_config['CONSTRUCTOR_PARAMETERS']['configuration']
            ue_id = device_config['CONSTRUCTOR_PARAMETERS']['serial_number']
            ue_class = self.get_device_class(class_name=device_config['CLASS'])
            config['access'] = device_config['CLASS'].lower().replace("ue", "")
            self.prepare_ueproxy_service(device_config)
            rpc_client = self.get_ueproxy_connection_client_by(config['ue_pc_address'])
            self.rpc_clients.add(rpc_client)
            constructor_params = {'name': device_name,
                                  'ue_id': ue_id,
                                  'configuration': config,
                                  'rpc_client': rpc_client}
            created_ue = instance_loader.create_class_instance(class_object=ue_class,
                                                               constructor_params=constructor_params)
            is_ue_preparation_successful = created_ue.prepare_ue()
            if not is_ue_preparation_successful:
                raise Exception("UE not prepared")
            return created_ue
        except KeyError as e:
            trace = traceback.format_exc()
            raise InvalidConfigurationContent(f"Configuration is not valid for IPhone UE: {device_name}. "
                                              f"Expected keyword: {e.args[0]}\nMore trace: {trace}")

    @classmethod
    def convert_device_type_2_device_class_fullname(cls, device_type):
        """
        Encapsulate convention how to produce full package.module.class name for given Device type

        (Default convention from ute_common_abstract_core/device_pool.py doesn't work for
        taf package structure)

        :param device_type: Device type (must be CamelCase name)
        :return: full package.module.class name
        """
        iphone_class = 'taf.ue.iphone.iphone_ue.IPhoneUe'
        ue_type2class_fullname = {'IPhoneUe': iphone_class,  # YAML-config class name
                                  'Iphone': iphone_class,    # Python-config class name
                                  }
        class_fullname = ue_type2class_fullname[device_type]
        return class_fullname

    def shutdown(self):
        """
        Shutdown

        avoid: RuntimeError: dictionary changed size during iteration
        """
        for rpc_client in self.rpc_clients:
            self.ueproxy_teardown(rpc_client)
